head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > P > validateAllItemsetData]<br/>DataList 모듈이 필터링 되었을때 BindItemSet 으로 연동된 컴포넌트에서 필터링된 아이템을 선택할 수 있게 합니다.",
    "validation" : [
        "DataList 모듈이 AutoComplete 컴포넌트에 BindItemSet 으로 정의된 경우에 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof autocomplete1 !== 'undefined') {
        autocomplete1.remove();
    }    

    // 조건 설정       
    let properties = {
        validateAllItemsetData: con_validateAllItemsetData.getText(),        
    };    

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

	let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strAutoComplete = '';
    let strNameSpace = $c.gcm.getNameSpace();  

    strTarget += '<w2:dataList ' + strNameSpace + ' ' + cList + ' id="target1" baseNode="list" repeatNode="map">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="label" name="name1" dataType="text"></w2:column>';
    strTarget += '<w2:column id="value" name="name2" dataType="text"></w2:column>';
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[1]]></label>';
    strTarget += '<value><![CDATA[1]]></value>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[2]]></label>';
    strTarget += '<value><![CDATA[2]]></value>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[3]]></label>';
    strTarget += '<value><![CDATA[3]]></value>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[4]]></label>';
    strTarget += '<value><![CDATA[4]]></value>';
    strTarget += '</w2:row>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';     

    // target 생성
    $p.data.create(strTarget);

    // AutoComplete 생성    
    strAutoComplete += '<w2:autoComplete ' + strNameSpace + ' style="width:200px; height:30px;">';
    strAutoComplete += '<w2:choices>';
    strAutoComplete += '<w2:itemset nodeset="data:target1">';
    strAutoComplete += '<w2:label ref="label"></w2:label>';
    strAutoComplete += '<w2:value ref="value"></w2:value>';
    strAutoComplete += '</w2:itemset>';
    strAutoComplete += '</w2:choices>';
    strAutoComplete += '</w2:autoComplete>';

    scwin.autocomplete1 = await $p.dynamicCreate(
        "autocomplete1",
        "autoComplete",
        strAutoComplete,
        grp_comp
    );

    scwin.btn_getValue();
}   



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter( {type:'row', colIndex:'label', key:"2", condition:'and'})    
    target1.setColumnFilter( {type:'row', colIndex:'label', key:"4", condition:'or'})    

    scwin.btn_getValue();
};



scwin.btn_getValue = function (e) {
    let rtn = '';
    rtn = autocomplete1.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + rtn);
}



scwin.btn_setValue_onclick = function (e) {
    autocomplete1.setValue(3);

    scwin.btn_getValue();
}
